-- ============================================================================
-- SAT Reading & Writing Ladder (/sat).
--
-- sat_progress      one row per student: their answers, modules and retired
--                   questions as a JSON blob. Owner-only, like users/experiences.
-- sat_explanations  short explanations, written once per question by
--                   /api/sat/explain (service role) and readable by every
--                   signed-in user.
-- sat-bank bucket   PRIVATE storage for the question bank (qs.json) and its
--                   figures (figs/*.png). Signed-in users can read it; nobody
--                   can list or write it from the browser. The questions come
--                   from the College Board question bank, which is why they
--                   are not in this (public) repository.
--
-- Run in: Supabase Dashboard -> SQL Editor -> + New query -> paste -> Run.
-- Idempotent: safe to run more than once.
-- ============================================================================

create table if not exists public.sat_progress (
  user_id uuid primary key references auth.users on delete cascade,
  data jsonb not null,
  updated_at timestamptz not null default now()
);
alter table public.sat_progress enable row level security;

drop policy if exists "sat_progress_owner" on public.sat_progress;
create policy "sat_progress_owner" on public.sat_progress
  for all using ((select auth.uid()) = user_id)
  with check ((select auth.uid()) = user_id);

create table if not exists public.sat_explanations (
  qid text primary key,
  data jsonb not null,
  created_by uuid,
  created_at timestamptz not null default now()
);
alter table public.sat_explanations enable row level security;

drop policy if exists "sat_explanations_signed_in_select" on public.sat_explanations;
create policy "sat_explanations_signed_in_select" on public.sat_explanations
  for select to authenticated using (true);
-- No insert/update policy: only the service role (the API route) writes.

insert into storage.buckets (id, name, public)
values ('sat-bank', 'sat-bank', false)
on conflict (id) do update set public = false;

drop policy if exists "sat_bank_signed_in_read" on storage.objects;
create policy "sat_bank_signed_in_read" on storage.objects
  for select to authenticated using (bucket_id = 'sat-bank');

-- Explanations already written in the original ladder.
insert into public.sat_explanations (qid, data) values
  ('38f92f17', '{"next": ["Ask: Is the new sentence adding more OR contradicting OR wrapping up?", "Here: adding another example of injustice-fighting. That''s \"Additionally.\""], "rule": "Transition: adding examples", "traps": {"B": "\"In conclusion\" means we''re wrapping up the whole discussion. But we''re only halfway through describing what Idár did.", "C": "\"For example\" would mean the League is an example of her work as a reporter. It''s not—it''s a separate action she took.", "D": "\"Rather\" shows a contrast or swap. Founding the League doesn''t contradict her reporter work. Both are examples of the same thing: fighting injustice."}, "why": "The first sentence says Idár fought injustice on both sides of the border. The second sentence gives one example: she was a reporter who supported Mexican people. The third sentence gives another example: she founded a group for Mexican Americans. \"Additionally\" shows we''re adding another example of her fighting injustice."}'::jsonb),
  ('3bb49e6e', '{"next": ["Ask: what is the main thing being compared to what? Here: night = a person.", "Look for repeated comparisons (clothes, face, hair, hands). If you see many, it''s an extended comparison.", "Eliminate answers about location, time changes, or multiple scenes."], "rule": "Extended comparison structure", "traps": {"A": "The text doesn''t mention rural or city locations. It''s just one description of night as a person.", "B": "There''s no sunrise mentioned. The poem only shows night, not sunrise or morning.", "D": "The poem doesn''t show night changing across seasons. It''s one single image of night as a human being."}, "why": "The poem describes night using human clothing and body parts: \"garment,\" \"face,\" \"veil,\" and \"hair.\" Night is treated like a person throughout."}'::jsonb),
  ('570dd854', '{"next": ["Find the exact question: what should the quotation explain?", "Check each answer: does the quote actually answer that question?", "Pick the choice where the quote directly fits what the question asks for."], "rule": "Quotation: what it explains", "traps": {"A": "Uses a quote about dialogue and power, not about what this specific sculpture represents.", "C": "Talks about the sistrum inspiration but doesn''t use a quote to explain what the sculpture represents.", "D": "The quote is about her general goal (dialogue, power, transformation), not what this particular sculpture symbolizes."}, "why": "The question asks for a quote that explains what the sculpture represents. Choice B uses Guirguis''s own words: \"women who have lifted and supported Egyptian society and culture.\" That''s exactly what the sculpture means."}'::jsonb),
  ('5ff1ba73', '{"next": ["Check: does the answer compare two or more cities?", "Check: does it show different guild-to-people ratios? Look for phrases like \"one guild for every X people.\""], "rule": "Evidence: supporting a claim with data", "traps": {"A": "Bordeaux had 80,000 people and Lyon had 143,000. They don''t have nearly equal populations—Lyon has almost twice as many.", "B": "The table shows Paris had 133 guilds but Lyon had only 72. Lyon didn''t have more guilds, so this doesn''t prove the point.", "D": "This only describes Paris. You need to compare at least two cities to show some cities had more guilds relative to population than others."}, "why": "The passage says guilds were more numerous in some cities relative to population. Choice C proves this by showing Rouen had one guild per 661 people, while Paris had one guild per 4,511 people. That''s a huge difference."}'::jsonb),
  ('684b8bd2', '{"next": ["Find the opening modifier: \"Far from being modern inventions.\"", "Ask: what IS an invention? Only drinking straws.", "Put that noun right after the comma."], "rule": "Modifier placement", "traps": {"A": "Puts \"Sumerians\" right after the modifier. Sumerians are people, not inventions.", "C": "Puts \"the use\" right after the modifier. The use isn''t an invention—the straws are.", "D": "Puts \"ancient Mesopotamia\" right after the modifier. A place isn''t an invention."}, "why": "The phrase \"Far from being modern inventions\" describes something that IS an invention. Only \"drinking straws\" fits. Answer B puts drinking straws right after the modifier."}'::jsonb),
  ('7297b3e0', '{"next": ["Read the blank sentence again. What time period does it mention? (Winter.)", "Look at your data. Find which species have higher numbers in winter than in spring and fall.", "Pick the answer that names those species and compares winter to the other seasons."], "rule": "Match evidence to claim", "traps": {"B": "This compares three species to each other, not one species across seasons. The claim is about seasons, not which species beat each other.", "C": "This talks about spring, not winter. The sentence says \"winter,\" so any answer about spring is wrong.", "D": "This talks about fall, not winter. The sentence says \"winter,\" so any answer about fall is wrong."}, "why": "The sentence says \"For some species, more fish were collected in the winter than the other two seasons.\" You need data showing a species with higher winter numbers than spring and fall. Choice A names two species (silver-biddy and milkfish) and says both had higher winter counts. That matches the claim perfectly."}'::jsonb),
  ('7cc8d51f', '{"next": ["Find the main point of each text: Fan says prices rise; F&P say long-term effects differ from short-term.", "Ask: what would F&P suggest Fan do differently? Look for time-related answers.", "Watch out for answers that add new ideas Text 2 never mentions (like locations or industry differences)."], "rule": "Cross-text connections", "traps": {"A": "Text 2 doesn''t say to compare different locations. Focarelli and Panetta care about time length, not geography.", "B": "Text 2 says merged companies get \"efficiency gains,\" meaning expenses go DOWN, not up.", "D": "Text 2 doesn''t claim newspapers are special. Their banking study suggests their idea applies to all industries."}, "why": "Fan found prices rise after a merger (bad for consumers). Focarelli and Panetta say research focuses too much on short-term effects, but long-term effects are actually good. They would want Fan to check if prices drop later."}'::jsonb),
  ('81da17d3', '{"next": ["Look for dates in both texts. Which painting came first?", "Check if Text 2 contradicts any claim in Text 1. Here: the \"first\" claim.", "Make sure the answer uses actual facts from both texts, not guesses about intention or influence."], "rule": "Cross-text connections: dates matter", "traps": {"A": "Neither text discusses how respected these painters were. The texts only talk about what they painted, not their fame or status.", "B": "Text 2 never says what Fontana intended with her painting. The author just points out the easel is there in the background.", "C": "Text 2 doesn''t say Fontana inspired Carracci. It only says Fontana''s work came earlier and also included painting references."}, "why": "Text 1 claims Carracci was \"the first artist to depict themself painting.\" Text 2 says Fontana''s painting from 1577 shows an easel in the background. That''s 8 years before Carracci''s 1585 painting. So Fontana was actually first."}'::jsonb),
  ('8cb0c10b', '{"next": ["Identify what Text 1 claims about language in graphic novels. (Here: it''s used \"sparingly.\")", "Find what Text 2 says about the same thing. (Here: language is essential, not optional.)", "Pick the answer that shows Text 2 disagreeing or adding to Text 1''s point."], "rule": "Cross-text comparison", "traps": {"B": "Text 1 never calls limited language a \"flaw.\" Text 1 just says it doesn''t fit the definition of literature. Text 2 wouldn''t agree something is flawed.", "C": "Text 1 never claims graphic novel stories are easy to understand. Text 2 says stories need both text AND images to make sense, not that some are harder.", "D": "Text 1 never says graphic novels are poorly written. Text 1 just says they use less language. Text 2 actually praises novels like Fun Home as beautifully written."}, "why": "Text 1 says language is used \"only sparingly\" in graphic novels. Text 2 argues that language is essential—\"without captions and dialogue, readers would be unable to understand.\" Text 2 directly challenges how little Text 1 values language''s role."}'::jsonb),
  ('e2aebe0a', '{"next": ["Ask: who or what is this passage really about? Here: Barrier Williams and what she did.", "Does it mainly describe a problem, a person''s actions, or general background info? Here: a person''s actions.", "Pick the answer that matches the main character and main action."], "rule": "Main purpose of passage", "traps": {"B": "The text mentions the Chicago Defender only as where she worked. It never says she used connections from that job to help women find work.", "C": "The text mentions why women wanted to move (job competition in the South), but doesn''t compare men''s reasons or say anything caused the start of the Great Migration.", "D": "The text mentions southern employment problems, but only to explain why women moved. The main focus is on what Barrier Williams did, not on describing those problems."}, "why": "The passage introduces Barrier Williams, then shows what she did to help Black women move north. The whole point is to show her important role in supporting these women during their relocation."}'::jsonb),
  ('e92b2a41', '{"next": ["Read what each author says about bluegrass history: Text 1 vs. Text 2.", "Find where they disagree most directly.", "The author who disagrees would call the other view illogical, unrealistic, etc. Pick the word that fits."], "rule": "Cross-text comparison", "traps": {"A": "Text 2 never mentions what music the purists themselves listen to. You can''t infer this.", "B": "Text 2 never talks about whether purists can enforce their views. This isn''t discussed.", "C": "Text 2 never mentions audience size or commercial success. This detail isn''t there."}, "why": "Text 2 says Bill Monroe mixed folk with jazz and blues to create bluegrass in the 1940s. Text 1 says purists want bluegrass to stick to pure folk roots. Text 2''s author would say the purists are wrong about bluegrass''s actual history."}'::jsonb),
  ('f5d60e4e', '{"next": ["Read the sentence without the blank. What''s the relationship between form and meaning here?", "Ask: Are they working together or against each other? Together = integral or connected word.", "Check if your word choice matches the tone and logic of the whole sentence."], "rule": "Words in context", "traps": {"A": "\"Antithetical\" means opposite. The text says form and content work TOGETHER, not against each other.", "B": "\"Resigned\" describes a person''s attitude, not a relationship between form and meaning. The form actively helps create meaning, not passively.", "C": "\"Invulnerable\" means can''t be harmed. Nothing in the text talks about the form being protected or under threat."}, "why": "The poem''s form and new content work together to create meaning. \"Integral\" means essential or necessary. Form is fundamental to how the poems convey their message."}'::jsonb),
  ('f8eacedb', '{"next": ["Find what each author claims about pastoralism''s role. Text 1: caused drying. Text 2: may have helped.", "The correct answer shows HOW they disagree, using specific evidence from Text 2.", "Wrong answers add ideas Text 2 never mentions or go against what Text 2 actually says."], "rule": "Cross-text comparison", "traps": {"B": "Text 2 says Neolithic practices may have helped, not hurt. Brierley doesn''t agree that their behaviors \"contributed\" to desertification.", "C": "Text 2 only shows pastoralism''s good side (preserved vegetation). It never admits pastoralism can be harmful.", "D": "Text 2 presents finished research with clear conclusions. It doesn''t say we need more studies."}, "why": "Text 1 says pastoralism dried out the Sahara. Text 2 says the humid period ended 500 years earlier than thought, so pastoralists couldn''t have caused it. Brierley would use this new timeline to say Wright is wrong."}'::jsonb),
  ('fc5d8203', '{"next": ["Ask: does Text 2 agree with Text 1''s main claim? Yes or no?", "If yes: look for HOW Text 2 changes or limits that claim. Find the \"but\" or \"however.\"", "Match that limitation to the answer."], "rule": "Cross-text connections: qualify a claim", "traps": {"A": "Text 2 doesn''t say bees felt stress instead of fun. It says other studies show bees CAN feel stress, but Galpayage''s study shows they might play for fun.", "B": "Text 2 specifically says insects'' emotions are \"very rudimentary,\" not complex. This contradicts the choice.", "C": "Text 2 never compares humans and insects. It only talks about whether bee emotions exist at all."}, "why": "Text 2 agrees bumblebees might play, but adds a big caveat: \"emotions in insects...are likely very rudimentary.\" Text 2 accepts Text 1''s idea but limits how much emotion we should think the bees actually have."}'::jsonb)
on conflict (qid) do nothing;
